import java.util.Scanner;

class Printer {
    int calculatePages(int ink) {
        return 0;
    }
}

class Inkjet extends Printer {
    int calculatePages(float ink) {
        return ink * 18;        
    }
}

class Laser extends Printer {
    int calculatePages(int ink) {
        return ink * 12;        
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String type = sc.nextLine();
        int ink = sc.next();

        Printer p = new Printer();     

        if(type.equals("InkJet"))       
        else
            p = new Laser();

        System.out.println("Printer: " + type);
        System.out.println("Ink Available: " + ink + " ml");
        System.out.println("Printable Pages: " + p.calculatePages(ink));

        sc.close();
    }
}

